class AdversarialServiceStub(betterproto.ServiceStub):
    """
    AdversarialService runs the three-ring adversarial pressure system, the
    bull/bear debate gate, and the three-persona risk positioning debate. The
    orchestrator calls this service each cycle before approving execution.
    """

    async def run_pressure(
        self,
        *,
        cycle: int = 0,
        variant_outputs: Optional[Dict[str, "VariantOutputs"]] = None,
        current_signals: Optional[Dict[str, float]] = None,
        strategy_params: Optional[Dict[str, float]] = None,
        run_ring2: bool = False,
        run_ring3: bool = False,
        run_debate: bool = False,
    ) -> RunPressureResponse:
        """
        RunPressure executes all three adversarial rings for a cycle and
        returns a consolidated report. This is the main entry point per cycle.
        """

        request = RunPressureRequest()
        request.cycle = cycle
        request.variant_outputs = variant_outputs
        request.current_signals = current_signals
        request.strategy_params = strategy_params
        request.run_ring2 = run_ring2
        request.run_ring3 = run_ring3
        request.run_debate = run_debate

        return await self._unary_unary(
            "/omega.v1.AdversarialService/RunPressure",
            request,
            RunPressureResponse,
        )

    async def run_debate(self, *, context: Optional["SignalContext"] = None) -> RunDebateResponse:
        """RunDebate runs the Bull/Bear debate gate on a signal context."""

        request = RunDebateRequest()
        if context is not None:
            request.context = context

        return await self._unary_unary(
            "/omega.v1.AdversarialService/RunDebate",
            request,
            RunDebateResponse,
        )

    async def resolve_risk(
        self, *, context: Optional["RiskContext"] = None
    ) -> ResolveRiskResponse:
        """
        ResolveRisk runs the three-persona risk debate for position sizing.
        """

        request = ResolveRiskRequest()
        if context is not None:
            request.context = context

        return await self._unary_unary(
            "/omega.v1.AdversarialService/ResolveRisk",
            request,
            ResolveRiskResponse,
        )

    async def record_gate_result(
        self,
        *,
        cycle: int = 0,
        gate_name: str = "",
        result: str = "",
        details: str = "",
        checked_at: Optional[datetime] = None,
    ) -> RecordGateResultResponse:
        """
        RecordGateResult persists the result of a simulation gate evaluation.
        """

        request = RecordGateResultRequest()
        request.cycle = cycle
        request.gate_name = gate_name
        request.result = result
        request.details = details
        if checked_at is not None:
            request.checked_at = checked_at

        return await self._unary_unary(
            "/omega.v1.AdversarialService/RecordGateResult",
            request,
            RecordGateResultResponse,
        )

    async def get_adversarial_report(self, *, cycle: int = 0) -> GetAdversarialReportResponse:
        """
        GetAdversarialReport retrieves the stored adversarial report for a
        cycle.
        """

        request = GetAdversarialReportRequest()
        request.cycle = cycle

        return await self._unary_unary(
            "/omega.v1.AdversarialService/GetAdversarialReport",
            request,
            GetAdversarialReportResponse,
        )

    async def stream_pressure_events(
        self, *, poll_interval_ms: int = 0
    ) -> AsyncGenerator[AdversarialPressureEvent, None]:
        """
        StreamPressureEvents streams adversarial pressure events as they occur.
        """

        request = StreamPressureEventsRequest()
        request.poll_interval_ms = poll_interval_ms

        async for response in self._unary_stream(
            "/omega.v1.AdversarialService/StreamPressureEvents",
            request,
            AdversarialPressureEvent,
        ):
            yield response


