class MemoryServiceStub(betterproto.ServiceStub):
    """
    MemoryService manages the triple-tier memory system:   - Working memory:
    in-process TTL-aware key/value store   - Episodic memory: timestamped
    SQLite-backed event log   - Semantic memory: generalized pattern store
    consolidated from episodes All writes go through this service so Go owns
    the SQLite layer. Python domain nodes call these RPCs instead of writing
    memory directly.
    """

    async def store_episode(
        self,
        *,
        namespace: str = "",
        event_type: str = "",
        content: Optional[Dict[str, str]] = None,
        tags: List[str] = [],
        importance: float = 0,
        cycle: int = 0,
    ) -> StoreEpisodeResponse:
        """StoreEpisode writes a new episodic memory entry."""

        request = StoreEpisodeRequest()
        request.namespace = namespace
        request.event_type = event_type
        request.content = content
        request.tags = tags
        request.importance = importance
        request.cycle = cycle

        return await self._unary_unary(
            "/omega.v1.MemoryService/StoreEpisode",
            request,
            StoreEpisodeResponse,
        )

    async def query_episodes(
        self,
        *,
        namespace: str = "",
        regime_tag: str = "",
        signal_type: str = "",
        start: Optional[datetime] = None,
        end: Optional[datetime] = None,
        current_regime: str = "",
        top_k: int = 0,
    ) -> QueryEpisodesResponse:
        """
        QueryEpisodes retrieves episodic memories matching the given filters.
        """

        request = QueryEpisodesRequest()
        request.namespace = namespace
        request.regime_tag = regime_tag
        request.signal_type = signal_type
        if start is not None:
            request.start = start
        if end is not None:
            request.end = end
